  // lattice where its pins are, the body centred over the middle one.
  static const width = 40.0;
  static const height = 72.0;
  static const componentSize = Size(width, height);

  /// The body; the legs below it are what the pins reach for.
  @override
  Rect bodyRect(Size size) => const Rect.fromLTRB(1.26, 5.6, 38.74, 52.2);

  @override
  Size get designSize => componentSize;

  @override
  List<PathArtLayer> get layers => switch (kind) {
    TransistorKind.npn => _npn,
    TransistorKind.pnp => _pnp,
    TransistorKind.nmos => _nmos,
    TransistorKind.pmos => _pmos,
  };

  static List<PathArtLayer> _withLabels(List<Path> label, List<Path> pins) => [
    (_legs, const Color(0xFF8C8C8C)),
    (_rim, const Color(0xFF595959)),
    (_dark, const Color(0xFF333333)),
    (label, const Color(0xFFE3E3E3)),
    (pins, const Color(0xFF666666)),
